from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NEW_YORK)

        self.spy = self.AddEquity("SPY", Resolution.MINUTE)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.RAW)

        self.option = self.AddOption("SPY", Resolution.MINUTE)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 90)
        )

        self.closes = RollingWindow[float](20)
        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy.Symbol,
            self.five_minute_consolidator
        )

        self.entry_order_id = None
        self.exit_order_id = None
        self.exit_submitted = False

        self.held_symbol = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = None
        previous_slow = None

        if self.closes.Count >= 20:
            previous_fast = sum(self.closes[i] for i in range(5)) / 5.0
            previous_slow = sum(self.closes[i] for i in range(20)) / 20.0

        self.closes.Add(float(bar.Close))

        if previous_fast is None:
            return

        current_fast = sum(self.closes[i] for i in range(5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(20)) / 20.0

        end_time = bar.EndTime
        eligible_time = (
            (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
            and
            (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
        )

        if not eligible_time:
            return

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish_crossover:
            self.TryEnterFromCurrentSlice()

    def TryEnterFromCurrentSlice(self):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self.entry_order_id is not None:
            return

        if self.Portfolio.Invested:
            return

        current_slice = self.CurrentSlice
        if current_slice is None:
            self.Debug("Entry skipped: no current Slice")
            return

        chain = current_slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Entry skipped: no option chain")
            return

        current_date = self.Time.date()
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= current_date
            and (contract.Expiry.date() - current_date).days >= 7
        })

        if not eligible_expirations:
            self.Debug("Entry skipped: no expiration >= 7 calendar days")
            return

        selected_expiry = eligible_expirations[0]
        minimum_strike = self.Securities[self.spy.Symbol].Price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.CALL
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call")
            return

        contract = sorted(
            candidates,
            key=lambda x: (float(x.Strike), str(x.Symbol))
        )[0]

        ticket = self.MarketOrder(contract.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {contract.Symbol} exp {selected_expiry} "
            f"strike {contract.Strike}"
        )

    def OnData(self, slice):
        self.HandleExpirationExit()
        self.HandleProfitTarget(slice)
        self.HandleTimeStop()

    def HandleProfitTarget(self, slice):
        if self.held_symbol is None or self.entry_fill_price is None:
            return

        if self.exit_submitted:
            return

        contract = self.GetHeldContractFromSlice(slice)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit("profit target")

    def HandleTimeStop(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.exit_submitted:
            return

        exchange_hours = self.Securities[self.held_symbol].Exchange.Hours
        prior_trading_day = exchange_hours.GetPreviousTradingDay(self.held_expiry)

        if (
            self.Time.date() == prior_trading_day.date()
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self.SubmitExit("pre-expiration time stop")

    def HandleExpirationExit(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.Time.date() < self.held_expiry.date():
            return

        self.no_entry_date = self.Time.date()

        if not self.exit_submitted:
            self.SubmitExit("expiration safeguard")

    def GetHeldContractFromSlice(self, slice):
        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == self.held_symbol:
                return contract

        return None

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_submitted:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            if order.Direction == OrderDirection.SELL:
                self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.exit_submitted = True
        self.Debug(f"Exit submitted: {reason} {self.held_symbol}")

    def OnOrderEvent(self, order_event):
        message = (order_event.Message or "").lower()
        if "exercise" in message or "assignment" in message:
            self.Debug(
                f"Unexpected option exercise/assignment: "
                f"{order_event.Symbol} {order_event.Message}"
            )

        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.FILLED:
                self.held_symbol = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date
                self.entry_fill_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_symbol} @ {self.entry_fill_price:.2f}"
                )
            elif order_event.Status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.Debug(f"Entry canceled/invalid: {order_event.Symbol}")
                self.entry_order_id = None

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
        ):
            if order_event.Status == OrderStatus.FILLED:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} @ "
                    f"{float(order_event.FillPrice):.2f}"
                )
                self.held_symbol = None
                self.held_expiry = None
                self.entry_fill_price = None
                self.exit_order_id = None
            elif order_event.Status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.Debug(f"Exit canceled/invalid: {order_event.Symbol}")

