from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(lambda universe: universe.IncludeWeeklys()
                         .Strikes(-100, 100)
                         .Expiration(0, 365))
        self.option_symbol = option.Symbol

        self.close_window = RollingWindow[float](21)
        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

        self.pending_entry_signal = False
        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.time_stop_submitted_date = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        self.close_window.Add(float(bar.Close))

        if self.close_window.Count < 21:
            return

        fast_previous = sum(self.close_window[i] for i in range(1, 6)) / 5.0
        slow_previous = sum(self.close_window[i] for i in range(1, 21)) / 20.0
        fast_current = sum(self.close_window[i] for i in range(0, 5)) / 5.0
        slow_current = sum(self.close_window[i] for i in range(0, 20)) / 20.0

        end_clock = bar.EndTime.time()
        eligible_time = time(9, 45) <= end_clock <= time(14, 30)

        if eligible_time and fast_previous <= slow_previous and fast_current > slow_current:
            self.pending_entry_signal = True

    def OnData(self, slice):
        self.HandleExpirationSafety()
        self.HandleExits(slice)

        if not self.pending_entry_signal:
            return

        self.pending_entry_signal = False

        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            return

        if self.HasOpenEntryOrder():
            return

        self.TryEnter(slice)

    def TryEnter(self, slice):
        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain.")
            return

        spot = float(self.Securities[self.spy].Price)
        if spot <= 0:
            self.Debug(f"{self.Time}: Entry skipped: invalid SPY price.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: Entry skipped: no expiration at least seven calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: Entry skipped: no qualifying call for {selected_expiry}.")
            return

        contract = min(candidates, key=lambda x: (float(x.Strike), str(x.Symbol)))
        ticket = self.MarketOrder(contract.Symbol, 1)

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                f"{self.Time}: Entry submitted: {contract.Symbol}, "
                f"expiry {contract.Expiry.date()}, strike {contract.Strike}."
            )

    def HandleExits(self, slice):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        if self.HasOpenExitOrder():
            return

        quote_bar = None
        if slice.QuoteBars.ContainsKey(self.held_contract):
            quote_bar = slice.QuoteBars[self.held_contract]

        if quote_bar is not None:
            bid = float(quote_bar.Bid.Close) if quote_bar.Bid is not None else 0.0
            ask = float(quote_bar.Ask.Close) if quote_bar.Ask is not None else 0.0

            if bid > 0 and ask > 0 and self.entry_price is not None:
                midpoint = (bid + ask) / 2.0
                if midpoint >= self.entry_price * 1.50:
                    self.SubmitExit("profit target")
                    return

        if (self.Time.date() == self.PreviousTradingDay(self.held_contract.ID.Date).date()
                and self.Time.time() >= time(15, 45)
                and self.time_stop_submitted_date != self.Time.date()):
            self.time_stop_submitted_date = self.Time.date()
            self.SubmitExit("15:45 pre-expiration time stop")

    def HandleExpirationSafety(self):
        if self.held_contract is None or self.Portfolio[self.held_contract].Quantity == 0:
            return

        if self.Time.date() >= self.held_contract.ID.Date.date():
            self.no_entry_date = self.Time.date()
            if not self.HasOpenExitOrder():
                self.SubmitExit("expiration safety liquidation")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        self.CancelOpenExitOrder()

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        if ticket is not None:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"{self.Time}: Exit submitted for {self.held_contract}: {reason}.")

    def PreviousTradingDay(self, expiry):
        candidate = expiry - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(datetime.combine(candidate, time.min)):
            candidate -= timedelta(days=1)

        return datetime.combine(candidate, time.min)

    def HasOpenEntryOrder(self):
        if self.entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.entry_order_id)
        return order is not None and order.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def HasOpenExitOrder(self):
        if self.exit_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.exit_order_id)
        return order is not None and order.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def CancelOpenExitOrder(self):
        if self.HasOpenExitOrder():
            self.Transactions.CancelOrder(self.exit_order_id, "Replacing exit order")

    def OnOrderEvent(self, order_event):
        if self.entry_order_id is not None and order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled: {self.held_contract} "
                    f"at {self.entry_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug(f"{self.Time}: Entry order did not fill: {order_event.Status}.")

        if self.exit_order_id is not None and order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled: {order_event.Symbol} "
                    f"at {float(order_event.FillPrice):.2f}."
                )
                self.exit_order_id = None
                self.held_contract = None
                self.entry_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        message = (order_event.Message or "").lower()
        if "exercise" in message or "assignment" in message:
            self.Debug(
                f"{self.Time}: Unexpected option exercise/assignment event: "
                f"{order_event.Symbol}, {order_event.Message}"
            )

