            self.pending_entry_signal = False
            self._try_enter(slice)

    def _on_five_minute_bar(self, sender, bar):
        end_time = bar.end_time.time()

        if len(self.closes) >= 20:
            prior_values = list(self.closes)
            prior_fast = sum(prior_values[-5:]) / 5.0
            prior_slow = sum(prior_values[-20:]) / 20.0
        else:
            prior_fast = None
            prior_slow = None

