        exchange_hours = self.securities[self.spy].exchange.hours

        while not exchange_hours.is_date_open(datetime.combine(candidate, time.min)):
            candidate -= timedelta(days=1)

        return candidate

    def _clear_completed_state(self):
        if self.entry_order_id is not None:
            order = self.transactions.get_order_by_id(self.entry_order_id)
            if order is not None and order.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
                OrderStatus.REJECTED
            ):
                self.entry_order_id = None

        if self.exit_order_id is not None:
            order = self.transactions.get_order_by_id(self.exit_order_id)
            if order is not None and order.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
                OrderStatus.REJECTED
            ):
                self.exit_order_id = None

        if (
            self.held_contract is not None
            and not self.portfolio[self.held_contract].invested
            and self.entry_order_id is None
        ):
            self.held_contract = None
            self.entry_price = None
            self.exit_order_id = None

    def on_order_event(self, order_event):
        if "Exercise" in str(order_event.order_type) or "Assignment" in str(order_event.order_type):
            self.debug(f"Unexpected exercise/assignment: {order_event.symbol}")

        if order_event.order_id == self.entry_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.held_contract = order_event.symbol
                self.entry_price = float(order_event.fill_price)
                self.entry_order_id = None
                self.debug(
                    f"Entry filled: {self.held_contract} @ {self.entry_price:.2f}"
                )
            elif order_event.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
                OrderStatus.REJECTED
            ):
                self.entry_order_id = None
                self.debug(f"Entry failed: {order_event.symbol}")

        if order_event.order_id == self.exit_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(f"Exit filled: {order_event.symbol} @ {order_event.fill_price:.2f}")
                self.exit_order_id = None
            elif order_event.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
                OrderStatus.REJECTED
            ):
                self.exit_order_id = None

