from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.Strikes(-1000, 1000).Expiration(
                timedelta(days=0), timedelta(days=365)
            )
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.signal_time = None
        self.held_symbol = None
        self.entry_order_id = None
        self.entry_price = None
        self.exit_order_id = None
        self.no_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.OnPreExpirationTimeStop
        )

    def OnFiveMinuteBar(self, sender, bar):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value

        self.fast.Update(IndicatorDataPoint(bar.EndTime, bar.Close))
        self.slow.Update(IndicatorDataPoint(bar.EndTime, bar.Close))

        current_ready = self.fast.IsReady and self.slow.IsReady
        if (previous_ready and current_ready and
                previous_fast <= previous_slow and
                self.fast.Current.Value > self.slow.Current.Value):
            self.signal_time = bar.EndTime

    def OnData(self, data):
        self.HandleExpirationProcessing()

        if self.held_symbol is not None:
            self.CheckProfitTarget(data)

        if self.signal_time != self.Time:
            return

        self.signal_time = None

        if not (time(9, 45) <= self.Time.time() <= time(14, 30)):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self.HasOpenEntryOrder():
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; no SPY option chain.")
            return

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug(f"{self.Time}: skipped entry; invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: skipped entry; no call expiry at least 7 calendar days out.")
            return

        expiry = eligible_expiries[0]
        minimum_strike = spot * 1.01
        candidates = [
            contract for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: skipped entry; no call at {expiry} meets 1% OTM strike rule."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: submitted entry for {selected.Symbol} "
            f"(expiry {expiry}, strike {selected.Strike})."
        )

    def CheckProfitTarget(self, data):
        if self.entry_price is None or self.exit_order_id is not None:
            return

        contract = self.GetHeldContractFromSlice(data)
        if contract is None:
            return

        if contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("profit target")

    def OnPreExpirationTimeStop(self):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        expiry = self.held_symbol.ID.Date.date()
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        next_open = exchange_hours.GetNextMarketOpen(self.Time, False)

        if next_open.date() == expiry:
            self.SubmitExit("pre-expiration 15:45 time stop")

    def HandleExpirationProcessing(self):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()
        if self.Time.date() >= expiry:
            self.no_entry_date = self.Time.date()
            if self.exit_order_id is None:
                self.Debug(
                    f"{self.Time}: expiration processing for {self.held_symbol}; liquidating."
                )
                self.SubmitExit("expiration processing")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: submitted exit for {self.held_symbol}; {reason}.")

    def GetHeldContractFromSlice(self, data):
        for chain in data.OptionChains.Values:
            if self.held_symbol in chain.Contracts:
                return chain.Contracts[self.held_symbol]
        return None

    def HasOpenEntryOrder(self):
        if self.entry_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, order_event):
        message = (order_event.Message or "").lower()
        if "exercise" in message or "assignment" in message:
            self.Debug(
                f"{self.Time}: unexpected option exercise or assignment: {order_event.Message}"
            )

        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: entry filled for {self.held_symbol} at {self.entry_price}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_id = None
                self.Debug(f"{self.Time}: entry order was not filled: {order_event.Status}.")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: exit filled for {order_event.Symbol} at {order_event.FillPrice}."
                )
                self.held_symbol = None
                self.entry_price = None
                self.exit_order_id = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None
                self.Debug(f"{self.Time}: exit order was not filled: {order_event.Status}.")

