        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self.SubmitExit("50% profit target")

    def FindHeldContract(self, slice):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_symbol:
                    return contract
        return None

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(datetime(candidate.year, candidate.month, candidate.day)):
            candidate -= timedelta(days=1)

        return candidate

    def SubmitExit(self, reason):
        if self.held_symbol is None or not self.IsHoldingOption() or self.HasOpenExitOrder():
            return

        for order in self.Transactions.GetOpenOrders():
            if order.Symbol == self.held_symbol:
                self.Transactions.CancelOrder(order.Id, f"Replacing open exit: {reason}")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_symbol}")

    def HasActivePositionOrEntry(self):
        return self.IsHoldingOption() or self.IsEntryOrderOpen()

    def IsHoldingOption(self):
        return (
            self.held_symbol is not None
            and self.Securities.ContainsKey(self.held_symbol)
            and self.Portfolio[self.held_symbol].Quantity != 0
        )

    def IsEntryOrderOpen(self):
        if self.entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.entry_order_id)
        return order is not None and order.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def HasOpenExitOrder(self):
        if self.exit_order_id is None:
