        if self.held_contract is None or self.Portfolio[self.held_contract].Quantity <= 0:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if today >= expiry_date:
            self.no_entry_date = today
            if self.exit_order_id is None:
                self.Debug(f"Unexpected expiration-day holding: {self.held_contract}.")
                self.SubmitExit(self.held_contract, "expiration protection")

    def SubmitExit(self, contract, reason):
        for order in self.Transactions.GetOpenOrders(contract):
            if order.Id != self.exit_order_id:
                self.Transactions.CancelOrder(order.Id)

        quantity = -self.Portfolio[contract].Quantity
        if quantity != 0:
            self.exit_order_id = self.MarketOrder(contract, quantity).OrderId
            self.Debug(f"Exit submitted ({reason}): {contract}.")

