        if "exercise" in message or "assignment" in message:
            self.Debug(f"Unexpected option exercise/assignment: {order_event.Message}")

        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug(f"Entry order closed without fill: {order_event.Symbol}.")

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}."
                )
                self.exit_order_id = None
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_contract = None
                    self.entry_price = None
